import{_ as e,o as i,c as o,a2 as d}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Manejo de las Cuatro Ramas de las Entidades Oscuras de Reemplazo","description":"","frontmatter":{},"headers":[],"relativePath":"es/59-黑暗置换体四类分支处置.md","filePath":"es/59-黑暗置换体四类分支处置.md"}'),n={name:"es/59-黑暗置换体四类分支处置.md"};function t(l,a,r,s,c,u){return i(),o("div",null,[...a[0]||(a[0]=[d('<h1 id="manejo-de-las-cuatro-ramas-de-las-entidades-oscuras-de-reemplazo" tabindex="-1">Manejo de las Cuatro Ramas de las Entidades Oscuras de Reemplazo <a class="header-anchor" href="#manejo-de-las-cuatro-ramas-de-las-entidades-oscuras-de-reemplazo" aria-label="Permalink to &quot;Manejo de las Cuatro Ramas de las Entidades Oscuras de Reemplazo&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Elemento</th><th>Contenido</th></tr></thead><tbody><tr><td>N.º de documento</td><td>59</td></tr><tr><td>Módulo</td><td>Razas y Formas de Vida</td></tr><tr><td>Palabras clave</td><td>Fusión simbiótica, separación y reubicación, sellado y monitoreo, disolución, manejo por ramas</td></tr></tbody></table><h2 id="i-marco-general-del-manejo-por-ramas" tabindex="-1">I. Marco General del Manejo por Ramas <a class="header-anchor" href="#i-marco-general-del-manejo-por-ramas" aria-label="Permalink to &quot;I. Marco General del Manejo por Ramas&quot;">​</a></h2><p>El manejo de las Entidades Oscuras de Reemplazo es el campo más complejo de la gobernanza de la vida en la Civilización Simbiótica del Ancla. A diferencia de los procesos de manejo en tres tipos para la vida anómala y la energía anómala, las Entidades Oscuras de Reemplazo, debido a su estructura especial de coexistencia de dos almas (véase <em>57-黑暗置换体起源与本质</em>), requieren planes de manejo por ramas más refinados. Según los principios éticos establecidos en <em>58-双魂伦理准则</em>, combinados con la etapa de desarrollo de la Entidad Oscura de Reemplazo, el estado del alma anfitriona original, las características del alma oscura y el nivel de riesgo, el manejo de las Entidades Oscuras de Reemplazo se divide en cuatro ramas: tipo fusión simbiótica, tipo separación y reubicación, tipo sellado y monitoreo, y tipo disolución.</p><p>La selección de los cuatro manejos por ramas sigue la siguiente lógica de decisión:</p><table tabindex="0"><thead><tr><th>Factor de decisión</th><th>Puntos de consideración</th></tr></thead><tbody><tr><td>Etapa de desarrollo</td><td>Las etapas primera a tercera priorizan el rescate; la cuarta etapa se evalúa con cautela; en la quinta etapa el anfitrión original ha perecido</td></tr><tr><td>Estado del alma anfitriona original</td><td>Si el alma anfitriona original aún existe, si puede expresar su voluntad, si hay posibilidad de recuperación</td></tr><tr><td>Características del alma oscura</td><td>Si el alma oscura tiene potencial de comunicación, si hay margen de reforma, el grado de destructividad</td></tr><tr><td>Nivel de riesgo</td><td>El grado de amenaza para la seguridad pública y los derechos e intereses de otros</td></tr><tr><td>Conclusión de la revisión ética</td><td>La opinión y adjudicación del Comité de Revisión Ética del Alma Dual</td></tr><tr><td>Voluntad del anfitrión original</td><td>La elección del alma anfitriona original cuando puede expresar su voluntad</td></tr></tbody></table><h2 id="ii-primer-tipo-manejo-de-fusion-simbiotica" tabindex="-1">II. Primer Tipo: Manejo de Fusión Simbiótica <a class="header-anchor" href="#ii-primer-tipo-manejo-de-fusion-simbiotica" aria-label="Permalink to &quot;II. Primer Tipo: Manejo de Fusión Simbiótica&quot;">​</a></h2><p>El manejo de fusión simbiótica es el manejo más positivo y constructivo entre las cuatro ramas, aplicable a las Entidades Oscuras de Reemplazo en las que el alma anfitriona original y el alma oscura tienen la posibilidad de alcanzar la reconciliación y lograr la fusión de almas.</p><h3 id="i-condiciones-aplicables" tabindex="-1">(I) Condiciones Aplicables <a class="header-anchor" href="#i-condiciones-aplicables" aria-label="Permalink to &quot;(I) Condiciones Aplicables&quot;">​</a></h3><p>El manejo de fusión simbiótica debe satisfacer simultáneamente las siguientes condiciones:</p><ol><li>La Entidad Oscura de Reemplazo está en la tercera etapa (período de formación de dos almas) o en el inicio de la cuarta etapa (inicio del período de dominación oscura); el alma anfitriona original aún existe y posee cierto grado de conciencia autónoma.</li><li>El alma anfitriona original expresa claramente la voluntad de intentar la fusión con el alma oscura, y esta voluntad se determina como genuina y autónoma.</li><li>El alma oscura posee cierta capacidad de comunicación, muestra características no puramente destructivas y tiene la posibilidad de aceptar la fusión.</li><li>El nivel de riesgo se evalúa como Segundo nivel (riesgo medio) o inferior, y el proceso de fusión no representará una amenaza incontrolable para la seguridad pública.</li><li>Aprobado por la revisión del Comité de Revisión Ética del Alma Dual.</li></ol><h3 id="ii-objetivo-del-manejo" tabindex="-1">(II) Objetivo del Manejo <a class="header-anchor" href="#ii-objetivo-del-manejo" aria-label="Permalink to &quot;(II) Objetivo del Manejo&quot;">​</a></h3><p>Guiando al alma anfitriona original y al alma oscura hacia la reconciliación, lograr la fusión orgánica de las dos almas, formando un alma nueva que posee tanto los recuerdos, la personalidad como el poder oscuro del anfitrión original. El alma nueva fusionada conserva la ciudadanía y los derechos legítimos del anfitrión original, al tiempo que obtiene la capacidad de manipular la energía oscura, convirtiéndose en un miembro especial de la civilización simbiótica.</p><h3 id="iii-pasos-del-manejo" tabindex="-1">(III) Pasos del Manejo <a class="header-anchor" href="#iii-pasos-del-manejo" aria-label="Permalink to &quot;(III) Pasos del Manejo&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Paso</th><th>Nombre</th><th>Contenido específico</th><th>Institución responsable</th></tr></thead><tbody><tr><td>Paso uno</td><td>Revisión ética</td><td>El Comité de Revisión Ética del Alma Dual realiza una revisión integral del plan de fusión, confirmando el cumplimiento de los principios éticos</td><td>Comité de Revisión Ética del Alma Dual</td></tr><tr><td>Paso dos</td><td>Guía de comunicación</td><td>En un entorno controlado, guías de almas profesionales asisten al alma anfitriona original y al alma oscura en la comunicación, promoviendo el entendimiento mutuo</td><td>Centro de Tratamiento de Almas + cultivadores</td></tr><tr><td>Paso tres</td><td>Negociación de reconciliación</td><td>Guiar a las dos almas hacia un acuerdo de reconciliación sobre la identidad fusionada, los recuerdos, las capacidades, las normas de comportamiento, etc.</td><td>Centro de Tratamiento de Almas + asesores legales</td></tr><tr><td>Paso cuatro</td><td>Preparación de la fusión</td><td>Realizar preparativos previos a la fusión como el acondicionamiento corporal, el equilibrio energético y la construcción psicológica</td><td>Equipo médico + instructores de cultivo</td></tr><tr><td>Paso cinco</td><td>Fusión de almas</td><td>Con la asistencia conjunta de cultivadores avanzados y terapeutas de almas, implementar la cirugía/ritual de fusión de almas</td><td>Cultivadores avanzados + terapeutas de almas</td></tr><tr><td>Paso seis</td><td>Estabilización posterior a la fusión</td><td>Realizar un tratamiento de estabilización para el alma nueva fusionada, monitoreando la integridad del alma y la adaptabilidad del cuerpo</td><td>Equipo médico + equipo de monitoreo</td></tr><tr><td>Paso siete</td><td>Confirmación de identidad</td><td>Confirmar la identidad del alma nueva fusionada, conservar la ciudadanía del anfitrión original y actualizar los archivos de identidad</td><td>Institución de registro de hogares + Oficina de Administración de la Vida</td></tr><tr><td>Paso ocho</td><td>Asistencia de integración</td><td>Proporcionar servicios auxiliares como asesoramiento psicológico, guía de cultivo e integración social para el individuo fusionado</td><td>Departamento de Asuntos de las Diez Mil Razas + comunidad</td></tr><tr><td>Paso nueve</td><td>Seguimiento a largo plazo</td><td>Realizar un seguimiento y monitoreo a largo plazo del individuo fusionado durante no menos de cinco años, evaluando la estabilidad de la fusión y la adaptabilidad social</td><td>Oficina de Administración de la Vida + comunidad</td></tr></tbody></table><h3 id="iv-gestion-posterior-a-la-fusion" tabindex="-1">(IV) Gestión Posterior a la Fusión <a class="header-anchor" href="#iv-gestion-posterior-a-la-fusion" aria-label="Permalink to &quot;(IV) Gestión Posterior a la Fusión&quot;">​</a></h3><p>Aunque el individuo fusionado conserva la ciudadanía del anfitrión original, debe aceptar una gestión especial:</p><ul><li><strong>Control de energía</strong>: el uso de la energía oscura por parte del individuo fusionado está estrictamente controlado; se requieren inspecciones energéticas periódicas y está prohibido el uso de energía oscura en lugares públicos.</li><li><strong>Supervisión de comportamiento</strong>: el individuo fusionado debe informar periódicamente su estado de comportamiento a la Oficina de Administración de la Vida y aceptar la supervisión y ayuda de la comunidad.</li><li><strong>Restricciones de cultivo</strong>: el individuo fusionado no puede cultivar técnicas que puedan agravar los atributos oscuros; los planes de cultivo deben ser aprobados.</li><li><strong>Plan de emergencia</strong>: establecer un plan de emergencia para la pérdida de control de la energía oscura en individuos fusionados; ante los primeros signos de pérdida de control, activar inmediatamente el control.</li><li><strong>Mecanismo de salida</strong>: si aparece inestabilidad grave o comportamiento peligroso persistente después de la fusión, puede realizarse una reevaluación y convertirse el tipo de manejo.</li></ul><h3 id="v-manejo-del-fracaso-de-la-fusion" tabindex="-1">(V) Manejo del Fracaso de la Fusión <a class="header-anchor" href="#v-manejo-del-fracaso-de-la-fusion" aria-label="Permalink to &quot;(V) Manejo del Fracaso de la Fusión&quot;">​</a></h3><p>La fusión de almas conlleva riesgo de fracaso; los planes de manejo del fracaso de la fusión:</p><ul><li><strong>Interrupción de la fusión</strong>: si ocurre inestabilidad grave durante el proceso de fusión, interrumpir inmediatamente la fusión y restaurar las dos almas a su estado previo a la fusión.</li><li><strong>Fusión incompleta</strong>: si aparece incompletitud del alma o división de la personalidad después de la fusión, transferir al manejo de separación y reubicación para el tratamiento posterior.</li><li><strong>Pérdida de control de la fusión</strong>: si el alma nueva después de la fusión muestra destructividad incontrolable, transferir inmediatamente al manejo de sellado y monitoreo o disolución.</li></ul><h2 id="iii-segundo-tipo-manejo-de-separacion-y-reubicacion" tabindex="-1">III. Segundo Tipo: Manejo de Separación y Reubicación <a class="header-anchor" href="#iii-segundo-tipo-manejo-de-separacion-y-reubicacion" aria-label="Permalink to &quot;III. Segundo Tipo: Manejo de Separación y Reubicación&quot;">​</a></h2><p>El manejo de separación y reubicación se aplica a las Entidades Oscuras de Reemplazo en las que el alma anfitriona original y el alma oscura no pueden fusionarse pero pueden separarse; mediante una cirugía de separación de almas, las dos almas se separan y se reubican respectivamente.</p><h3 id="i-condiciones-aplicables-1" tabindex="-1">(I) Condiciones Aplicables <a class="header-anchor" href="#i-condiciones-aplicables-1" aria-label="Permalink to &quot;(I) Condiciones Aplicables&quot;">​</a></h3><ol><li>La Entidad Oscura de Reemplazo está en la tercera o cuarta etapa; el alma anfitriona original aún existe y tiene posibilidad de recuperación.</li><li>El intento de fusión de las dos almas ha fracasado o no tiene las condiciones para la fusión.</li><li>La evaluación técnica considera factible la separación de almas, y el alma anfitriona original puede sobrevivir de forma independiente tras la separación.</li><li>El alma anfitriona original expresa claramente la voluntad de ser separada.</li><li>Aprobado por la revisión del Comité de Revisión Ética del Alma Dual.</li></ol><h3 id="ii-objetivo-del-manejo-1" tabindex="-1">(II) Objetivo del Manejo <a class="header-anchor" href="#ii-objetivo-del-manejo-1" aria-label="Permalink to &quot;(II) Objetivo del Manejo&quot;">​</a></h3><p>Mediante la cirugía de separación de almas, separar el alma anfitriona original del alma oscura; el alma anfitriona original regresa al cuerpo para reanudar la vida normal, mientras que el alma oscura se coloca en un contenedor o instalación dedicados para control e investigación.</p><h3 id="iii-pasos-del-manejo-1" tabindex="-1">(III) Pasos del Manejo <a class="header-anchor" href="#iii-pasos-del-manejo-1" aria-label="Permalink to &quot;(III) Pasos del Manejo&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Paso</th><th>Nombre</th><th>Contenido específico</th><th>Institución responsable</th></tr></thead><tbody><tr><td>Paso uno</td><td>Revisión ética</td><td>El Comité de Revisión Ética del Alma Dual revisa el plan de separación, confirmando la necesidad y viabilidad de la separación</td><td>Comité de Revisión Ética del Alma Dual</td></tr><tr><td>Paso dos</td><td>Preparación de la separación</td><td>Realizar preparativos previos a la separación como evaluación corporal, inspección del estado del alma y ajuste del equilibrio energético</td><td>Equipo médico + terapeutas de almas</td></tr><tr><td>Paso tres</td><td>Separación de almas</td><td>Con la asistencia de cultivadores avanzados y terapeutas de almas, implementar la cirugía de separación de almas para separar las dos almas del cuerpo</td><td>Cultivadores avanzados + terapeutas de almas</td></tr><tr><td>Paso cuatro</td><td>Reubicación del anfitrión original</td><td>Reimplantar el alma anfitriona original en el cuerpo, realizando estabilización del alma y rehabilitación corporal</td><td>Equipo médico</td></tr><tr><td>Paso cinco</td><td>Colocación del alma oscura</td><td>Colocar el alma oscura separada en un contenedor dedicado de contención de almas y almacenarla en una instalación de sellado de almas</td><td>Oficina de Administración de la Vida + equipo técnico</td></tr><tr><td>Paso seis</td><td>Recuperación del anfitrión original</td><td>Realizar rehabilitación corporal integral, tratamiento psicológico y recuperación de cultivo para el anfitrión original, ayudándolo a volver a la vida normal</td><td>Equipo médico + consejeros psicológicos</td></tr><tr><td>Paso siete</td><td>Restauración de identidad</td><td>Confirmar la restauración completa de la identidad y los derechos del anfitrión original y actualizar los archivos de identidad</td><td>Institución de registro de hogares</td></tr><tr><td>Paso ocho</td><td>Gestión del alma oscura</td><td>Realizar un monitoreo e investigación continuos del alma oscura separada, explorando la posibilidad de su reforma o disolución</td><td>Oficina de Administración de la Vida + institución de investigación científica</td></tr></tbody></table><h3 id="iv-colocacion-del-alma-oscura-separada" tabindex="-1">(IV) Colocación del Alma Oscura Separada <a class="header-anchor" href="#iv-colocacion-del-alma-oscura-separada" aria-label="Permalink to &quot;(IV) Colocación del Alma Oscura Separada&quot;">​</a></h3><p>El alma oscura separada se coloca de la siguiente manera:</p><ul><li><strong>Contenedor de alma</strong>: el alma oscura se coloca en un contenedor dedicado de contención de almas equipado con dispositivos como blindaje energético, supresión de conciencia y bloqueo de seguridad.</li><li><strong>Instalación de sellado</strong>: el contenedor se almacena en una instalación dedicada de sellado de almas que implementa el más alto nivel de gestión de seguridad.</li><li><strong>Monitoreo continuo</strong>: realizar un monitoreo continuo las 24 horas de la actividad de conciencia y las fluctuaciones energéticas del alma oscura.</li><li><strong>Investigación y utilización</strong>: bajo estricta revisión ética, pueden realizarse investigaciones científicas sobre el alma oscura, explorando la esencia de la Energía Abisal y los métodos de purificación.</li><li><strong>Manejo final</strong>: según los resultados de la investigación y la evaluación de riesgos, tomar una decisión de manejo final para el alma oscura: reforma en existencia no destructiva, sellado a largo plazo o purificación y disolución.</li></ul><h3 id="v-riesgos-de-la-separacion-y-respuestas" tabindex="-1">(V) Riesgos de la Separación y Respuestas <a class="header-anchor" href="#v-riesgos-de-la-separacion-y-respuestas" aria-label="Permalink to &quot;(V) Riesgos de la Separación y Respuestas&quot;">​</a></h3><p>La cirugía de separación de almas conlleva los siguientes riesgos, para los cuales deben formularse planes de respuesta:</p><table tabindex="0"><thead><tr><th>Riesgo</th><th>Plan de respuesta</th></tr></thead><tbody><tr><td>El alma anfitriona original se daña durante la separación</td><td>Fortalecer el alma antes de la separación; cultivadores avanzados brindan protección completa durante la separación</td></tr><tr><td>El cuerpo del anfitrión original no se adapta tras la separación</td><td>Realizar rehabilitación corporal integral y tratamiento de estabilización del alma tras la separación</td></tr><tr><td>El alma oscura escapa durante la separación</td><td>La separación se realiza en la instalación de seguridad de más alto nivel, equipada con múltiples dispositivos de contención</td></tr><tr><td>Separación incompleta, energía oscura residual</td><td>Realizar un tratamiento de purificación profunda tras la separación para eliminar la energía oscura residual</td></tr><tr><td>Trauma psicológico en el alma anfitriona original tras la separación</td><td>Proporcionar asesoramiento psicológico a largo plazo y tratamiento mental</td></tr></tbody></table><h2 id="iv-tercer-tipo-manejo-de-sellado-y-monitoreo" tabindex="-1">IV. Tercer Tipo: Manejo de Sellado y Monitoreo <a class="header-anchor" href="#iv-tercer-tipo-manejo-de-sellado-y-monitoreo" aria-label="Permalink to &quot;IV. Tercer Tipo: Manejo de Sellado y Monitoreo&quot;">​</a></h2><p>El manejo de sellado y monitoreo se aplica a las Entidades Oscuras de Reemplazo que no pueden fusionarse ni separarse, pero cuyo alma anfitriona original aún existe y que no tienen condiciones de disolución inmediata; mediante medios de sellado, su peligro se controla, con monitoreo a largo plazo y evaluación continua.</p><h3 id="i-condiciones-aplicables-2" tabindex="-1">(I) Condiciones Aplicables <a class="header-anchor" href="#i-condiciones-aplicables-2" aria-label="Permalink to &quot;(I) Condiciones Aplicables&quot;">​</a></h3><ol><li>La Entidad Oscura de Reemplazo está en la cuarta etapa (período de dominación oscura); el alma anfitriona original está profundamente suprimida pero aún no ha perecido.</li><li>Tanto la fusión como la separación carecen de viabilidad técnica o sus riesgos son demasiado altos.</li><li>El nivel de riesgo de la Entidad Oscura de Reemplazo es Tercer nivel (riesgo alto), pero aún no ha alcanzado el grado que exige disolución inmediata.</li><li>El alma anfitriona original aún tiene una débil esperanza de recuperación, requiriendo tiempo y condiciones para esperar un punto de inflexión.</li><li>El Comité de Revisión Ética del Alma Dual revisa y aprueba el plan de sellado.</li></ol><h3 id="ii-objetivo-del-manejo-2" tabindex="-1">(II) Objetivo del Manejo <a class="header-anchor" href="#ii-objetivo-del-manejo-2" aria-label="Permalink to &quot;(II) Objetivo del Manejo&quot;">​</a></h3><p>Mediante medios de sellado, suprimir el poder y la actividad del alma oscura, controlar el peligro de la Entidad Oscura de Reemplazo, protegiendo al mismo tiempo el alma anfitriona original de la aniquilación completa, esperando en el monitoreo a largo plazo la maduración de las oportunidades de recuperación o manejo.</p><h3 id="iii-metodos-de-sellado" tabindex="-1">(III) Métodos de Sellado <a class="header-anchor" href="#iii-metodos-de-sellado" aria-label="Permalink to &quot;(III) Métodos de Sellado&quot;">​</a></h3><p>Según el nivel de poder y las características de la Entidad Oscura de Reemplazo, elegir los siguientes métodos de sellado:</p><table tabindex="0"><thead><tr><th>Método de sellado</th><th>Principio</th><th>Objetivos aplicables</th></tr></thead><tbody><tr><td>Sellado energético</td><td>Utilizar matrices o dispositivos de sellado para suprimir el flujo y la salida de la energía oscura</td><td>Entidades Oscuras de Reemplazo de nivel de poder bajo a medio</td></tr><tr><td>Sellado espacial</td><td>Sellar la Entidad Oscura de Reemplazo en un espacio aislado independiente, cortando el contacto con el exterior</td><td>Entidades Oscuras de Reemplazo de alto nivel de poder o infecciosas</td></tr><tr><td>Sellado de conciencia</td><td>Suprimir la actividad de conciencia del alma oscura, colocándola en un estado latente o semilatente</td><td>Entidades Oscuras de Reemplazo con conciencia activa y capacidad de ataque al alma</td></tr><tr><td>Sellado múltiple</td><td>Utilizar simultáneamente varios métodos de sellado, formando múltiples capas de protección</td><td>Entidades Oscuras de Reemplazo de nivel de poder extremadamente alto o con múltiples características peligrosas</td></tr><tr><td>Sellado del Ancla</td><td>Utilizar los atributos originarios de la energía del Ancla para el sellado, el método de sellado más poderoso</td><td>Entidades Oscuras de Reemplazo peligrosas a nivel cósmico</td></tr></tbody></table><h3 id="iv-pasos-del-manejo" tabindex="-1">(IV) Pasos del Manejo <a class="header-anchor" href="#iv-pasos-del-manejo" aria-label="Permalink to &quot;(IV) Pasos del Manejo&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Paso</th><th>Nombre</th><th>Contenido específico</th><th>Institución responsable</th></tr></thead><tbody><tr><td>Paso uno</td><td>Revisión ética</td><td>El Comité de Revisión Ética del Alma Dual revisa el plan de sellado, confirmando la necesidad y adecuación del sellado</td><td>Comité de Revisión Ética del Alma Dual</td></tr><tr><td>Paso dos</td><td>Preparación del sellado</td><td>Preparar la matriz/dispositivo/espacio de sellado, asignando la energía y el personal requeridos</td><td>Equipo técnico + cultivadores avanzados</td></tr><tr><td>Paso tres</td><td>Dominio y control</td><td>Con la cooperación del equipo de seguridad, dominar la Entidad Oscura de Reemplazo, garantizando que no ocurran accidentes durante el proceso de sellado</td><td>Departamento de Seguridad + cultivadores avanzados</td></tr><tr><td>Paso cuatro</td><td>Implementación del sellado</td><td>Implementar el sellado según el plan, suprimiendo el poder y la actividad del alma oscura</td><td>Cultivadores avanzados + selladores</td></tr><tr><td>Paso cinco</td><td>Verificación del sellado</td><td>Verificar la efectividad y estabilidad del sellado, confirmando que el peligro de la Entidad Oscura de Reemplazo ha sido controlado</td><td>Equipo técnico + equipo de monitoreo</td></tr><tr><td>Paso seis</td><td>Transferencia y colocación</td><td>Transferir la Entidad Oscura de Reemplazo sellada a una instalación dedicada de sellado y monitoreo</td><td>Departamento de Seguridad + Oficina de Administración de la Vida</td></tr><tr><td>Paso siete</td><td>Monitoreo continuo</td><td>Realizar un monitoreo continuo las 24 horas del estado del sellado, verificando periódicamente la estabilidad del sellado</td><td>Equipo de monitoreo</td></tr><tr><td>Paso ocho</td><td>Reevaluación periódica</td><td>Realizar una reevaluación integral cada seis meses, evaluando el estado del alma anfitriona original, las características del alma oscura y la estabilidad del sellado, determinando si existe la posibilidad de ajustar el tipo de manejo</td><td>Grupo de expertos en identificación + Comité de Revisión Ética</td></tr><tr><td>Paso nueve</td><td>Mantenimiento del sellado</td><td>Mantener y reforzar periódicamente el sellado para evitar su debilitamiento o daño</td><td>Selladores + equipo técnico</td></tr></tbody></table><h3 id="v-normas-de-las-instalaciones-de-sellado-y-monitoreo" tabindex="-1">(V) Normas de las Instalaciones de Sellado y Monitoreo <a class="header-anchor" href="#v-normas-de-las-instalaciones-de-sellado-y-monitoreo" aria-label="Permalink to &quot;(V) Normas de las Instalaciones de Sellado y Monitoreo&quot;">​</a></h3><ul><li><strong>Ubicación</strong>: las instalaciones de sellado y monitoreo se ubican en áreas remotas con geología estable, entorno energético estable y población escasa, o en planos aislados independientes.</li><li><strong>Construcción</strong>: las instalaciones adoptan estructuras de protección múltiples, incluyendo tres capas de protección: barreras físicas, barreras energéticas y bloqueo espacial.</li><li><strong>Equipamiento</strong>: equipadas con dispositivos de monitoreo de sellado de alta precisión, sistemas de refuerzo automáticos, sistemas de respuesta de emergencia y sistemas de energía de respaldo.</li><li><strong>Personal</strong>: implementar un sistema de servicio de 24 horas, con selladores, monitores, agentes de seguridad y personal de respuesta de emergencia.</li><li><strong>Emergencia</strong>: formular diversos planes de emergencia para daño del sellado, fuga del alma oscura, desaparición del alma anfitriona original, etc., con simulacros periódicos.</li></ul><h3 id="vi-levantamiento-y-conversion-del-sellado" tabindex="-1">(VI) Levantamiento y Conversión del Sellado <a class="header-anchor" href="#vi-levantamiento-y-conversion-del-sellado" aria-label="Permalink to &quot;(VI) Levantamiento y Conversión del Sellado&quot;">​</a></h3><p>En las siguientes circunstancias, el sellado puede levantarse o convertirse el tipo de manejo:</p><ul><li><strong>Recuperación del anfitrión original</strong>: si el alma anfitriona original se recupera gradualmente durante el período de sellado y posee las condiciones de separación o fusión, puede levantarse el sellado y convertirse al tipo separación y reubicación o fusión simbiótica.</li><li><strong>Reforma del alma oscura</strong>: si el alma oscura muestra potencial de reforma durante el período de sellado, puede levantarse el sellado en condiciones controladas para intentos de reforma.</li><li><strong>Fallo del sellado</strong>: si el sellado sufre daño o debilitamiento irreparable, y el peligro de la Entidad Oscura de Reemplazo es incontrolable, puede convertirse al tipo disolución.</li><li><strong>Desaparición del anfitrión original</strong>: si el alma anfitriona original perece por completo durante el período de sellado y la Entidad Oscura de Reemplazo se convierte en una existencia puramente oscura, puede convertirse al tipo disolución o continuar el sellado según su peligro.</li></ul><h2 id="v-cuarto-tipo-manejo-de-disolucion" tabindex="-1">V. Cuarto Tipo: Manejo de Disolución <a class="header-anchor" href="#v-cuarto-tipo-manejo-de-disolucion" aria-label="Permalink to &quot;V. Cuarto Tipo: Manejo de Disolución&quot;">​</a></h2><p>El manejo de disolución es el manejo más severo entre las cuatro ramas, aplicable a las Entidades Oscuras de Reemplazo que no pueden rescatarse y son extremadamente peligrosas; mediante la aniquilación del alma oscura (y cuando es necesario, la aniquilación de todo el cuerpo), se elimina la amenaza.</p><h3 id="i-condiciones-aplicables-3" tabindex="-1">(I) Condiciones Aplicables <a class="header-anchor" href="#i-condiciones-aplicables-3" aria-label="Permalink to &quot;(I) Condiciones Aplicables&quot;">​</a></h3><p>El manejo de disolución se aplica a las siguientes situaciones:</p><ol><li>La Entidad Oscura de Reemplazo está en la quinta etapa (período de reemplazo completo); el alma anfitriona original ha perecido por completo, el cuerpo está totalmente controlado por el alma oscura, convirtiéndose en una existencia puramente oscura.</li><li>La Entidad Oscura de Reemplazo está en la cuarta etapa; el alma anfitriona original aún existe pero no puede recuperarse, la fusión, la separación y el sellado son inviables, y su peligro continúa escalando.</li><li>El nivel de riesgo de la Entidad Oscura de Reemplazo es Cuarto nivel (riesgo extremadamente alto), con poder destructivo de nivel cósmico, amenazando directamente la supervivencia civilizacional, y otros métodos de manejo no pueden controlar su amenaza.</li><li>En el manejo de sellado y monitoreo, el sellado ha fallado y no puede reaplicarse, y el peligro de la Entidad Oscura de Reemplazo es incontrolable.</li><li>El Comité de Revisión Ética del Alma Dual revisa y aprueba el plan de disolución (las emergencias de riesgo extremadamente alto pueden tratarse primero y aprobarse retroactivamente).</li></ol><h3 id="ii-principios-de-disolucion" tabindex="-1">(II) Principios de Disolución <a class="header-anchor" href="#ii-principios-de-disolucion" aria-label="Permalink to &quot;(II) Principios de Disolución&quot;">​</a></h3><p>El manejo de disolución implica la aniquilación de la vida y debe seguir estrictamente los siguientes principios:</p><ul><li><strong>Principio de último recurso</strong>: la disolución debe ser el último recurso cuando todos los demás métodos de manejo son inviables.</li><li><strong>Principio de proporcionalidad</strong>: la intensidad de la disolución debe corresponder al grado de amenaza; el uso excesivo de la fuerza está prohibido.</li><li><strong>Principio de sufrimiento mínimo</strong>: la disolución debe adoptar métodos sin dolor y rápidos en la medida de lo posible, reduciendo el sufrimiento del alma oscura (y del alma anfitriona original, si aún existe).</li><li><strong>Principio de respeto al anfitrión original</strong>: si el alma anfitriona original aún existe, debe mantenerse lúcida y digna en la medida de lo posible antes de la disolución; si es necesario, permitir que el anfitrión original se despida de familiares y amigos.</li><li><strong>Principio de registro completo</strong>: el proceso de disolución se registra por completo, formando un archivo completo para revisión y trazabilidad.</li><li><strong>Principio de revisión posterior</strong>: tras completarse la disolución, realizar una revisión posterior, evaluando la necesidad y adecuación de la disolución y resumiendo las lecciones aprendidas.</li></ul><h3 id="iii-metodos-de-disolucion" tabindex="-1">(III) Métodos de Disolución <a class="header-anchor" href="#iii-metodos-de-disolucion" aria-label="Permalink to &quot;(III) Métodos de Disolución&quot;">​</a></h3><p>Según el nivel de poder y las características de la Entidad Oscura de Reemplazo, elegir los siguientes métodos de disolución:</p><table tabindex="0"><thead><tr><th>Método de disolución</th><th>Principio</th><th>Objetivos aplicables</th></tr></thead><tbody><tr><td>Disolución por Purificación de Luz Sagrada</td><td>Utilizar Energía de Luz Sagrada de alta intensidad para purificar el alma oscura, haciendo que se disipe en la luz</td><td>Entidades Oscuras de Reemplazo de nivel de poder bajo a medio</td></tr><tr><td>Arte de Aniquilación del Alma</td><td>Atacar y aniquilar directamente el núcleo del alma oscura, provocando su desaparición completa</td><td>Entidades Oscuras de Reemplazo de alto nivel de poder</td></tr><tr><td>Disolución por Exilio Espacial</td><td>Exiliar la Entidad Oscura de Reemplazo al espacio del vacío o al fin de los tiempos, haciéndola disolverse en la decadencia espaciotemporal</td><td>Entidades Oscuras de Reemplazo con fuerte defensa física</td></tr><tr><td>Disolución por el Origen del Ancla</td><td>Invocar la energía originaria del Ancla, descomponiendo la Entidad Oscura de Reemplazo y devolviéndola al origen del universo</td><td>Entidades Oscuras de Reemplazo peligrosas a nivel cósmico</td></tr><tr><td>Disolución Conjunta de Poderes de Múltiples Planos</td><td>Varias Potencias Supremas del Plano unen fuerzas, usando poder absoluto para suprimir y aniquilar la Entidad Oscura de Reemplazo</td><td>Entidades Oscuras de Reemplazo de nivel de poder extremadamente alto</td></tr><tr><td>Disolución por Autodetonación Inducida</td><td>Bajo estricto control, inducir la autodetonación de la energía oscura de la Entidad Oscura de Reemplazo, disolviéndola en la explosión energética</td><td>Entidades Oscuras de Reemplazo con energía inestable</td></tr></tbody></table><h3 id="iv-pasos-del-manejo-1" tabindex="-1">(IV) Pasos del Manejo <a class="header-anchor" href="#iv-pasos-del-manejo-1" aria-label="Permalink to &quot;(IV) Pasos del Manejo&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Paso</th><th>Nombre</th><th>Contenido específico</th><th>Institución responsable</th></tr></thead><tbody><tr><td>Paso uno</td><td>Revisión ética/aprobación de emergencia</td><td>En circunstancias normales, revisado y aprobado por el Comité de Revisión Ética del Alma Dual; en emergencias de riesgo extremadamente alto, ordenado por el responsable de mayor rango en el sitio, con aprobación retroactiva</td><td>Comité de Revisión Ética del Alma Dual / responsable de mayor rango en el sitio</td></tr><tr><td>Paso dos</td><td>Formulación del plan</td><td>Formular un plan detallado de disolución, incluyendo métodos de disolución, asignación de fuerzas, medidas de seguridad, planes de emergencia y evaluación de impacto ambiental</td><td>Cuartel general de mando de combate + grupo de expertos técnicos</td></tr><tr><td>Paso tres</td><td>Ensamblaje de fuerzas</td><td>Reunir los cultivadores, el personal técnico, el equipo y los recursos energéticos requeridos para la disolución</td><td>Departamento de Seguridad + cultivadores avanzados</td></tr><tr><td>Paso cuatro</td><td>Bloqueo de zona</td><td>Bloquear la zona de disolución, evacuar al personal circundante y establecer cordones de seguridad</td><td>Departamento de Seguridad + gobierno local</td></tr><tr><td>Paso cinco</td><td>Dominio y supresión</td><td>Primero usar fuerza de supresión para controlar las acciones de la Entidad Oscura de Reemplazo, evitando su fuga o mayor destrucción</td><td>Cultivadores avanzados + fuerzas de seguridad</td></tr><tr><td>Paso seis</td><td>Implementación de la disolución</td><td>Implementar la disolución según el plan, con monitoreo integral del proceso; ante cualquier anomalía, activar inmediatamente el plan de emergencia</td><td>Cultivadores avanzados + equipo técnico</td></tr><tr><td>Paso siete</td><td>Confirmación de desaparición</td><td>Confirmar que el alma oscura (y el cuerpo) ha perecido por completo, inspeccionando la presencia de energía residual o fragmentos de alma</td><td>Equipo de monitoreo + grupo de expertos</td></tr><tr><td>Paso ocho</td><td>Restauración ambiental</td><td>Realizar la restauración ambiental de la zona de disolución, eliminando la energía oscura residual y restableciendo el equilibrio ecológico</td><td>Departamento de Ecología y Medio Ambiente</td></tr><tr><td>Paso nueve</td><td>Manejo de consecuencias</td><td>Notificar a los familiares y amigos del anfitrión original (si el anfitrión original ha perecido), manejar el patrimonio del anfitrión original y realizar asesoramiento psicológico</td><td>Departamento de asuntos civiles + consejeros psicológicos</td></tr><tr><td>Paso diez</td><td>Archivo y revisión posterior</td><td>Archivar los registros completos del proceso de disolución y realizar una revisión posterior, evaluando la necesidad y adecuación</td><td>Oficina de Administración de la Vida + Comité de Revisión Ética</td></tr></tbody></table><h3 id="v-procedimiento-de-disolucion-de-emergencia" tabindex="-1">(V) Procedimiento de Disolución de Emergencia <a class="header-anchor" href="#v-procedimiento-de-disolucion-de-emergencia" aria-label="Permalink to &quot;(V) Procedimiento de Disolución de Emergencia&quot;">​</a></h3><p>Para las Entidades Oscuras de Reemplazo de Cuarto nivel (riesgo extremadamente alto) que amenazan directamente la supervivencia civilizacional, se aplica el procedimiento de disolución de emergencia:</p><ol><li>El responsable de mayor rango en el sitio puede ordenar directamente el inicio de la disolución de emergencia, sin revisión ética previa, pero debe informar al Comité de Revisión Ética del Alma Dual para su registro dentro de las 24 horas posteriores a la disolución.</li><li>La disolución de emergencia puede movilizar el más alto nivel de fuerza y recursos energéticos de la civilización, incluida la invocación centralizada de la energía del Ancla y la acción conjunta de múltiples Potencias Supremas del Plano.</li><li>El objetivo prioritario de la disolución de emergencia es eliminar la amenaza y proteger la vida y la seguridad civilizacional, no perseguir la &quot;elegancia&quot; o &quot;ausencia de dolor&quot; del método de disolución (pero el daño colateral debe minimizarse en la medida de lo posible).</li><li>Después de la disolución de emergencia, debe realizarse una evaluación y restauración ambiental integrales para prevenir la energía oscura residual y los desastres secundarios.</li><li>Los casos de disolución de emergencia deben someterse a revisión posterior y análisis profundo, resumiendo las lecciones aprendidas y mejorando los mecanismos de alerta y manejo.</li></ol><h2 id="vi-mecanismo-de-conversion-de-los-cuatro-manejos-por-ramas" tabindex="-1">VI. Mecanismo de Conversión de los Cuatro Manejos por Ramas <a class="header-anchor" href="#vi-mecanismo-de-conversion-de-los-cuatro-manejos-por-ramas" aria-label="Permalink to &quot;VI. Mecanismo de Conversión de los Cuatro Manejos por Ramas&quot;">​</a></h2><p>El manejo de las Entidades Oscuras de Reemplazo no es fijo; según los cambios de situación durante el proceso de manejo, es posible la conversión entre las cuatro ramas:</p><table tabindex="0"><thead><tr><th>Dirección de conversión</th><th>Condiciones de conversión</th><th>Procedimiento de conversión</th></tr></thead><tbody><tr><td>Fusión → Separación</td><td>El intento de fusión fracasa o aparece inestabilidad grave tras la fusión</td><td>Reevaluación; tras la aprobación de la revisión ética, convertir a separación</td></tr><tr><td>Fusión → Sellado</td><td>La fusión fracasa y la separación es inviable; se necesita control de riesgos</td><td>Reevaluación; tras la aprobación de la revisión ética, convertir a sellado</td></tr><tr><td>Fusión → Disolución</td><td>La fusión pierde el control; el alma nueva tiene destructividad incontrolable</td><td>Evaluación de emergencia; convertir inmediatamente a disolución</td></tr><tr><td>Separación → Sellado</td><td>La separación fracasa o el anfitrión original no puede recuperarse tras la separación; se necesita control de riesgos</td><td>Reevaluación; tras la aprobación de la revisión ética, convertir a sellado</td></tr><tr><td>Separación → Disolución</td><td>El alma oscura escapa durante la separación y es incontrolable</td><td>Evaluación de emergencia; convertir inmediatamente a disolución</td></tr><tr><td>Sellado → Fusión</td><td>Durante el período de sellado, el alma anfitriona original se recupera y posee condiciones de fusión</td><td>Descubierto en la reevaluación periódica; tras la aprobación de la revisión ética, convertir a fusión</td></tr><tr><td>Sellado → Separación</td><td>Durante el período de sellado, el alma anfitriona original se recupera y posee condiciones de separación</td><td>Descubierto en la reevaluación periódica; tras la aprobación de la revisión ética, convertir a separación</td></tr><tr><td>Sellado → Disolución</td><td>El sellado falla y no puede reaplicarse; el peligro es incontrolable</td><td>Evaluación de emergencia; convertir inmediatamente a disolución</td></tr><tr><td>Disolución → Otros</td><td>La disolución es el último recurso; una vez implementada, es irreversible</td><td>No aplicable</td></tr></tbody></table><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>El manejo de las cuatro ramas de las Entidades Oscuras de Reemplazo es la culminación de la gobernanza de la vida en la Civilización Simbiótica del Ancla. Desde el rescate activo de la fusión simbiótica, hasta el corte preciso de la separación y reubicación, la espera paciente del sellado y monitoreo, y el último recurso de la disolución, las cuatro ramas forman un espectro de manejo completo del más benigno al más severo, cubriendo todas las situaciones posibles de las Entidades Oscuras de Reemplazo. Este sistema de manejo defiende tanto la línea de base ética de &quot;hacer todo esfuerzo por salvar cada alma&quot; como la línea de base de seguridad de &quot;eliminar resueltamente las amenazas incontrolables&quot;, encarnando el exquisito equilibrio de la civilización simbiótica entre la ética de la vida y la gobernanza de la seguridad.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>57-黑暗置换体起源与本质 (Origen y Esencia de las Entidades Oscuras de Reemplazo)</li><li>58-双魂伦理准则 (Directrices Éticas del Alma Dual)</li><li>54-奇特生命三类处置流程 (Proceso de Tratamiento de los Tres Tipos de Vida Anómala)</li><li>48-司法体系与裁决机制 (Sistema Judicial y Mecanismo de Adjudicación)</li></ul>',74)])])}const g=e(n,[["render",t]]);export{p as __pageData,g as default};
